function M.sample(stage, tex_x, tex_y)
	local st = M.STAGES[stage] or M.STAGES[0]
	if not st then return false end
	local g = M.GRID
	local w = M.BODY.width
	local h = M.BODY.height
	if tex_x < 0 or tex_y < 0 or tex_x >= w or tex_y >= h then return false end
	local cx = math.floor(tex_x / w * g)
	local cy = math.floor(tex_y / h * g)
	if cx < 0 or cy < 0 or cx >= g or cy >= g then return false end
	local row = st.bits[cy + 1]
	if not row then return false end
	return (row & (1 << cx)) ~= 0
end

--- Enumerate solid 32×32 cells as body texture centers (for break smoke / rocks).
-- Cached per stage; safe for gameplay (no PNG scan).
local _solid_cache = {}
function M.list_solid_cells(stage)
	stage = tonumber(stage) or 0
	if _solid_cache[stage] then
		return _solid_cache[stage]
	end
	local st = M.STAGES[stage] or M.STAGES[0]
	local out = {}
	if not st then
		_solid_cache[stage] = out
		return out
	end
	local g = M.GRID
	local w = M.BODY.width
	local h = M.BODY.height
	for cy = 0, g - 1 do
		local row = st.bits[cy + 1]
		if row and row ~= 0 then
			for cx = 0, g - 1 do
				if (row & (1 << cx)) ~= 0 then
					out[#out + 1] = {
						cx = cx,
						cy = cy,
						tex_x = (cx + 0.5) * w / g,
						tex_y = (cy + 0.5) * h / g,
					}
				end
			end
		end
	end
	_solid_cache[stage] = out
	return out
end

--- Cells solid in from_stage but not in to_stage (break silhouette delta).
function M.list_diff_cells(from_stage, to_stage)
	local a = M.list_solid_cells(from_stage)
	local out = {}
	for i = 1, #a do
		local c = a[i]
		if not M.sample(to_stage, c.tex_x, c.tex_y) then
			out[#out + 1] = c
		end
	end
	return out
end

return M
